import numpy as np
from statsmodels.tsa.stattools import adfuller

def spread(y, x, beta, alpha=0.0):
    """The combination y - beta * x - alpha, as an array."""
    return np.asarray(y) - beta * np.asarray(x) - alpha


def adf_pvalue(s):
    """ADF p-value of s, with a constant and lags by AIC, to 4 places."""
    p = adfuller(s, autolag="AIC")[1]
    return round(float(p), 4)

