widget.solution:
import numpy as np
from statsmodels.tsa.stattools import adfuller

def best_beta_by_adf(y, x, betas):
    """The beta in betas whose y - beta * x has the most negative ADF statistic."""
    y, x = np.asarray(y), np.asarray(x)
    best, best_stat = None, np.inf
    for b in betas:
        stat = adfuller(y - b * x, autolag="AIC")[0]
        if stat < best_stat:
            best, best_stat = b, stat
    return round(float(best), 4)

